""" Elon Musk (X-shape) """


def main():
    """Elon Musk (X-shape)"""
    raw = input().strip().split()
    size = int(raw[0])
    symbol = raw[1]

    for row in range(size):
        line = []
        for col in range(size):
            if col in (row, size - 1 - row):
                if symbol == "#":
                    line.append("#")
                else:
                    dist = abs(row - size // 2)
                    line.append(chr(ord(symbol) + dist))
            else:
                line.append("-")
        print("".join(line))


if __name__ == "__main__":
    main()

""" Arrow """


def main():
    """Arrow"""
    dirs = input().strip()
    n = int(input())
    arrows = []
    for d in dirs:
        lines = []
        for row in range(2 * n - 1):
            depth = min(row, 2 * n - 2 - row)
            stars = n - depth
            if d == "R":
                lines.append(" " * (2 * depth) + "*" * stars)
            else:
                lines.append(" " * (n - 1 - depth) + "*" * stars)
        arrows.append("\n".join(lines))
    print("\n\n".join(arrows))


if __name__ == "__main__":
    main()

